def rule(ctx):
    def get_type(k):
        if 0 <= k < len(ctx.types):
            return ctx.types[k]
        return None

    def score_robot(r):
        t = get_type(r.type)
        w = t["work_time"] if t is not None else 10.0
        return (r.count * 10.0 + (r.hours + w) - r.duties_left * 0.2, r.idx)

    avail_sorted = sorted(ctx.available, key=score_robot)
    actions = [("reuse", r) for r in avail_sorted]

    def score_type(k):
        t = get_type(k)
        if t is None or ctx.left[k] <= 0:
            return (float('inf'), k)
        swt = t.get("single_work_time", 1.0)
        if swt <= 0:
            swt = 1.0
        duties = t.get("continue_max_work", 0) / swt
        capacity = duties * t.get("work_time", 0)
        maint = t.get("maintenance_time", 0)
        charge = t.get("charge_time", 0)
        score = -capacity + maint * 0.5 + charge * 0.1
        if k == ctx.gene_type:
            score -= 10.0
        return (score, k)

    valid_types = [k for k in range(len(ctx.types)) if get_type(k) is not None and ctx.left[k] > 0]
    types_sorted = sorted(valid_types, key=score_type)
    for k in types_sorted:
        actions.append(("new", k))

    if not actions:
        actions.append(("new", ctx.gene_type))
    return actions

