def rule(ctx):
    n_robots = len(ctx.robots)
    if n_robots > 0:
        total_count = 0
        total_hours = 0.0
        for r in ctx.robots:
            total_count += r.count
            total_hours += r.hours
        if total_count > 0:
            avg_duty = total_hours / total_count
        else:
            sum_wt = 0.0
            for r in ctx.robots:
                t = ctx.types[r.type]
                if t is not None:
                    sum_wt += t["work_time"]
            avg_duty = sum_wt / n_robots if n_robots > 0 else 1.0
    else:
        avg_duty = 1.0
    if avg_duty <= 0:
        avg_duty = 1.0

    try:
        slack = ctx.capacity - ctx.remaining
    except Exception:
        slack = 0.0

    def avail_key(r):
        t = ctx.types[r.type]
        if t is None:
            work_time = 0.0
        else:
            work_time = t["work_time"]
        projected_equiv = (r.count + 1) + (r.hours + work_time) / avg_duty
        penalty = 0.0
        if r.duties_left <= 1:
            if slack < 2.0 * work_time:
                penalty = 2.0
        return (projected_equiv + penalty, -r.duties_left, r.count, r.hours, r.ready if r.ready is not None else 0.0, r.idx)

    sorted_avail = sorted(ctx.available, key=avail_key)

    types_list = []
    for k in range(len(ctx.types)):
        t = ctx.types[k]
        if t is None or ctx.left[k] <= 0:
            continue
        work_time = t["work_time"]
        out_travel = t["out_travel_time"]
        return_travel = t["return_travel_time"]
        charge = t["charge_time"]
        single_work = t["single_work_time"]
        continue_max = t["continue_max_work"]
        maint = t["maintenance_time"]
        cycle = out_travel + work_time + return_travel + charge
        if cycle <= 0:
            cycle = 1.0
        if single_work > 0:
            max_duties = continue_max / single_work
        else:
            max_duties = 1.0
        if max_duties < 1.0:
            max_duties = 1.0
        if ctx.remaining <= work_time * max_duties:
            score = work_time / cycle
        else:
            score = (work_time * max_duties) / (cycle * max_duties + maint)
        types_list.append((k, score, work_time, ctx.left[k]))
    types_list.sort(key=lambda x: (-x[1], -x[2], -x[3], x[0]))

    actions = []
    for r in sorted_avail:
        actions.append(("reuse", r))
    for (k, _, _, _) in types_list:
        actions.append(("new", k))
    if not actions:
        actions.append(("new", ctx.gene_type))
    return actions

def rule(ctx):
    def avail_key(r):
        return (r.count, r.hours, -r.budget, r.idx)
    ordered = sorted(ctx.available, key=avail_key)
    actions = [("reuse", r) for r in ordered]

    def type_score(k):
        t = ctx.types[k]
        work = t['work_time']
        single = t['single_work_time']
        maxw = t['continue_max_work']
        charge = t['charge_time']
        maint = t['maintenance_time']
        out = t['out_travel_time']
        ret = t['return_travel_time']
        duties = maxw / single if single > 0 else 1.0
        if duties < 1.0:
            duties = 1.0
        cycle = work + out + ret + charge
        if cycle <= 0:
            cycle = 1.0
        total_time = duties * cycle + maint
        if total_time <= 0:
            return 0.0
        return (duties * work) / total_time

    candidates = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]
    new_types = []
    gt = ctx.gene_type
    if gt in candidates:
        new_types.append(gt)
        candidates.remove(gt)

    def cand_key(k):
        t = ctx.types[k]
        return (-type_score(k), t['maintenance_time'], t['charge_time'], k)

    candidates.sort(key=cand_key)
    new_types.extend(candidates)
    for k in new_types:
        actions.append(("new", k))

    if not actions:
        actions.append(("new", ctx.gene_type))
    return actions

