        return (score, -t['continue_max_work'], t['maintenance_time'], t['charge_time'], k)

    candidates.sort(key=new_key)
    for k in candidates:
        actions.append(("new", k))

    if not actions:
        actions.append(("new", ctx.gene_type))
    return actions

def rule(ctx):
    def reuse_key(r):
        t = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
        if t is None:
            ready = r.ready if r.ready is not None else 0
            return (r.count, r.hours, 0, 0, ready, r.idx)
        cmw = t['continue_max_work']
        if r.first_maint is None and cmw > 0:
            maint_debt = (cmw - r.budget) * t['work_time'] // cmw
        else:
            maint_debt = 0
        ready = r.ready if r.ready is not None else 0
        return (r.count, r.hours + maint_debt, -r.duties_left, -r.budget, ready, r.idx)

    actions = []
    for r in sorted(ctx.available, key=reuse_key):
        actions.append(("reuse", r))

    gene = ctx.gene_type
    if gene is not None and 0 <= gene < len(ctx.types) and ctx.types[gene] is not None and ctx.left[gene] > 0:
        actions.append(("new", gene))

    def type_key(k):
        t = ctx.types[k]
        cmw = t['continue_max_work'] if t is not None else 0
        sw = t['single_work_time'] if t is not None else 1
        if sw <= 0:
            sw = 1
        duties = cmw // sw
        wt = t['work_time'] if t is not None else 0
        return (-duties, -ctx.left[k], -wt, k)

    candidates = []
    for k in range(len(ctx.types)):
        if k == gene:
            continue
        if ctx.types[k] is not None and ctx.left[k] > 0:
            candidates.append(k)

    for k in sorted(candidates, key=type_key):
        actions.append(("new", k))

    return actions

