def rule(ctx):
    robots = ctx.robots
    n = len(robots)

    if n > 0:
        total_count = 0
        total_hours = 0.0
        for r in robots:
            total_count += r.count
            total_hours += r.hours
        avg_count = total_count / float(n)
        avg_hours = total_hours / float(n)
    else:
        avg_count = 0.0
        avg_hours = 0.0

    sum_work = 0.0
    num_work = 0
    for p in ctx.types:
        if p is not None:
            w = p.get("work_time", 10.0)
            if w is None or w <= 0:
                w = 10.0
            sum_work += w
            num_work += 1
    avg_work = sum_work / num_work if num_work > 0 else 10.0
    if avg_work <= 0:
        avg_work = 10.0

    horizon = ctx.T if ctx.T is not None and ctx.T > 0 else 1.0
    rem_frac = ctx.remaining / horizon
    if rem_frac < 0:
        rem_frac = 0.0
    elif rem_frac > 1:
        rem_frac = 1.0

    def avail_key(r):
        p = None
        if 0 <= r.type < len(ctx.types):
            p = ctx.types[r.type]

        work = avg_work
        if p is not None:
            w = p.get("work_time", avg_work)
            if w is not None and w > 0:
                work = w

        hour_gap = (r.hours - avg_hours) / max(1.0, avg_work)
        load = (r.count - avg_count) + 0.35 * hour_gap

        dl = r.duties_left if r.duties_left is not None else 1
        if dl < 1:
            dl = 1
        maint_guard = 0.0
        if dl < 3:
            maint_guard = rem_frac * (3.0 - dl) / 3.0 * 0.45

        ready = r.ready
        if ready is None:
            if r.last_end is not None:
                ready = r.last_end
            else:
                ready = ctx.t
        wait = ctx.t - ready
        if wait < 0:
            wait = 0.0
        rotate = -0.12 * (wait / horizon)

        band = 0 if r.count <= avg_count + 0.5 else 1
        return (band, load + maint_guard + rotate, r.count, r.hours, -r.budget, r.idx)

    actions = []
    if ctx.available:
        ordered = sorted(ctx.available, key=avail_key)
        for r in ordered:
            actions.append(("reuse", r))

    def ceil_pos(x):
        if x <= 0.0:
            return 0
        i = int(x)
        if x > i:
            i += 1
        return i

    remaining = ctx.remaining
    if remaining < 0:
        remaining = 0.0

    def type_key(k):
        p = ctx.types[k]

        work = p.get("work_time", 10.0)
        if work is None or work <= 0:
            work = 10.0

        single = p.get("single_work_time", work)
        if single is None or single <= 0:
            single = work

        cont = p.get("continue_max_work", single)
        if cont is None or cont <= 0:
            cont = single

        out = p.get("out_travel_time", 0.0) or 0.0
        ret = p.get("return_travel_time", 0.0) or 0.0
        charge = p.get("charge_time", 0.0) or 0.0
        maint = p.get("maintenance_time", 0.0) or 0.0

        duties = cont / single
        if duties < 1.0:
            duties = 1.0

        cycle_time = work + out + ret + charge
        if cycle_time <= 0:
            cycle_time = work if work > 0 else 1.0

        cycle_len = duties * cycle_time + maint
        if cycle_len <= 0:
            cycle_len = 1.0

        coverage = duties * work
        if coverage <= 0:
            coverage = work

        cap = (remaining / cycle_len) * coverage
        if cap < work:
            cap = work
        if cap <= 0:
            cap = 1.0

        need = remaining / cap
        req = int(need)
        if need > req:
            req += 1
        if req < 1:
            req = 1

        total_cap = req * cap
        leftover = total_cap - remaining
        if leftover < 0:
            leftover = 0.0

        waste = leftover / max(1.0, work * req)
        overhead = (req * maint) / max(1.0, remaining)
        gene_bonus = 0.0 if k == ctx.gene_type else 0.012

        return (req, waste + 0.55 * overhead + gene_bonus, maint, -cycle_time, -ctx.left[k], k)

    candidates = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and k < len(ctx.left) and ctx.left[k] > 0:
            candidates.append(k)

    candidates.sort(key=type_key)
    for k in candidates:
        actions.append(("new", k))

    if not actions:
        actions.append(("new", ctx.gene_type))

    return actions

def rule(ctx):
    t = ctx.t
    T = ctx.T if ctx.T and ctx.T > 0 else 1.0
    remaining = ctx.remaining
    if remaining is None:
        remaining = T - t
    if remaining < 0:
        remaining = 0.0

    robots = ctx.robots
    n = len(robots)

    def params(k):
        if k is not None and 0 <= k < len(ctx.types) and ctx.types[k] is not None:
            return ctx.types[k]
        return None

    type_count = {}
    for r in robots:
        type_count[r.type] = type_count.get(r.type, 0) + 1

    target_work = None
    if type_count:
        best_t = None
        best_c = -1
        for k in type_count:
            c = type_count[k]
            if c > best_c or (c == best_c and (best_t is None or k < best_t)):
                best_c = c
                best_t = k
        p = params(best_t)
        if p is not None:
            target_work = p.get("work_time", 10.0) or 10.0

    if target_work is None:
        p = params(ctx.gene_type)
        if p is not None:
            target_work = p.get("work_time", 10.0) or 10.0
        else:
            target_work = 10.0

    def fair_key(r):
        p = params(r.type)
        if p is None:
            work = 10.0
            cont = 1.0
            budget = r.budget if r.budget is not None else cont
        else:
            work = p.get("work_time", 10.0) or 10.0
            cont = p.get("continue_max_work", 1.0) or 1.0
            budget = r.budget if r.budget is not None else cont

        if work <= 0:
            work = 10.0
        if cont <= 0:
            cont = 1.0

        used = (cont - budget) / cont
        if used < 0:
            used = 0.0
        if used > 1:
            used = 1.0

        hour_units = r.hours / 10.0
        index = 0.55 * r.count + 0.30 * hour_units + 0.15 * used

        ready = r.ready if r.ready is not None else t
        wait = t - ready
        if wait < 0:
            wait = 0.0
        index = index - 0.0001 * wait

        dl = r.duties_left if r.duties_left is not None else 0
        return (index, r.count, r.hours, -dl, r.idx)

    def alt_key(r):
        p = params(r.type)
        if p is None:
            cont = 1.0
            budget = r.budget if r.budget is not None else cont
        else:
            cont = p.get("continue_max_work", 1.0) or 1.0
            budget = r.budget if r.budget is not None else cont

        if cont <= 0:
            cont = 1.0

        used = (cont - budget) / cont
        if used < 0:
            used = 0.0
        if used > 1:
            used = 1.0

        dl = r.duties_left if r.duties_left is not None else 1
        red = 1 if dl <= 1 else 0
        return (-red, -used, r.count, -dl, r.idx)

    actions = []

    if ctx.available:
        ordered = sorted(ctx.available, key=fair_key)
        actions.append(("reuse", ordered[0]))
        if len(ordered) > 1:
            tail = sorted(ordered[1:], key=alt_key)
            for r in tail:
                actions.append(("reuse", r))

    valid = []
    for k in range(len(ctx.types)):
        if k >= len(ctx.left) or ctx.left[k] <= 0:
            continue
        p = params(k)
        if p is None:
            continue

        work = p.get("work_time", 10.0) or 10.0
        single = p.get("single_work_time", work) or work
        cont = p.get("continue_max_work", 1.0) or 1.0
        out = p.get("out_travel_time", 0.0) or 0.0
        ret = p.get("return_travel_time", 0.0) or 0.0
        charge = p.get("charge_time", 0.0) or 0.0
        maint = p.get("maintenance_time", 0.0) or 0.0

        if single <= 0:
            single = work if work > 0 else 10.0

        duties = cont / single if single > 0 else 1.0
        if duties < 1.0:
            duties = 1.0

        cycle = work + out + ret + charge
        if cycle <= 0:
            cycle = work if work > 0 else 1.0

        span = duties * cycle
        fit = 0.0 if work <= remaining + 1e-9 else (work - remaining)
        cover = 0 if span >= remaining - 1e-9 else 1
        diff = abs(work - target_work)
        valid.append((k, work, span, maint, fit, cover, diff))

    any_cover = False
    for item in valid:
        if item[4] <= 1e-9 and item[5] == 0:
            any_cover = True
            break

    if any_cover:
        def new_key(item):
            k = item[0]
            maint = item[3]
            fit = item[4]
            cover = item[5]
            diff = item[6]
            gene = 0 if k == ctx.gene_type else 1
            return (fit, cover, diff, maint, gene, -ctx.left[k], k)
    else:
        def new_key(item):
            k = item[0]
            span = item[2]
            maint = item[3]
            fit = item[4]
            diff = item[6]
            gene = 0 if k == ctx.gene_type else 1
            return (fit, -span, maint, diff, gene, -ctx.left[k], k)

    for item in sorted(valid, key=new_key):
        actions.append(("new", item[0]))

    if not actions:
        actions.append(("new", ctx.gene_type))

    return actions

