def rule(ctx):
    def param(t, name, default):
        if t is None:
            return default
        v = t.get(name, default)
        if v is None:
            return default
        return v

    n = len(ctx.robots)
    if n > 0:
        total_count = 0
        total_hours = 0.0
        total_prog = 0.0
        for r in ctx.robots:
            total_count += r.count
            total_hours += r.hours
            t = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
            maxw = param(t, 'continue_max_work', 1.0)
            if maxw <= 0:
                maxw = 1.0
            prog = (maxw - r.budget) / maxw
            if prog < 0.0:
                prog = 0.0
            elif prog > 1.0:
                prog = 1.0
            total_prog += prog
        avg_count = total_count / n
        avg_hours = total_hours / n
        avg_prog = total_prog / n
    else:
        avg_count = 0.0
        avg_hours = 0.0
        avg_prog = 0.0

    def reuse_key(r):
        t = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
        work = param(t, 'work_time', 1.0)
        if work <= 0:
            work = 1.0
        maxw = param(t, 'continue_max_work', 1.0)
        if maxw <= 0:
            maxw = 1.0
        prog = (maxw - r.budget) / maxw
        if prog < 0.0:
            prog = 0.0
        elif prog > 1.0:
            prog = 1.0
        count_need = avg_count - r.count
        hours_need = (avg_hours - r.hours) / work
        maint_need = avg_prog - prog
        idle = 0.0
        if r.last_end is not None:
            idle = ctx.t - r.last_end
            if idle < 0.0:
                idle = 0.0
            if ctx.T > 0:
                idle = idle / ctx.T
        dl = r.duties_left if r.duties_left is not None else 0
        score = -(2.0 * count_need + 0.8 * hours_need + 0.7 * maint_need + 0.15 * idle)
        score += 0.03 * dl
        return (score, r.count, r.hours, -r.budget, r.idx)

    def type_key(k):
        t = ctx.types[k]
        work = param(t, 'work_time', 1.0)
        if work <= 0:
            work = 1.0
        single = param(t, 'single_work_time', 1.0)
        if single <= 0:
            single = 1.0
        maxw = param(t, 'continue_max_work', 1.0)
        if maxw <= 0:
            maxw = 1.0
        charge = param(t, 'charge_time', 0.0)
        maint = param(t, 'maintenance_time', 0.0)
        out = param(t, 'out_travel_time', 0.0)
        ret = param(t, 'return_travel_time', 0.0)
        duties = maxw / single
        if duties < 1.0:
            duties = 1.0
        cycle = work + out + ret + charge
        if cycle <= 0:
            cycle = 1.0
        time_no_maint = duties * cycle
        if ctx.remaining <= time_no_maint:
            events = 0
        else:
            block = time_no_maint + maint
            if block <= 0:
                block = 1.0
            q = ctx.remaining / block
            events = int(q)
            if events < q:
                events += 1
            if events < 1:
                events = 1
        throughput = duties * work
        return (events, -throughput, maint, cycle, k)

